import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.BvlN9b-o.js";const k=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function o(d,e,l,p,h,r){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>当前版本完成了 T01：<strong>Web → 生成 SDK → Axum → 真实 PostgreSQL</strong>，以及与源码同步的在线教程。注册、Markdown 业务与附件属于后续实施票；当前页面会真实显示服务连接状态。</p><h2 id="准备工具" tabindex="-1">准备工具 <a class="header-anchor" href="#准备工具" aria-label="Permalink to &quot;准备工具&quot;">​</a></h2><p>使用仓库固定的 Rust 1.96.0、Node 24.18.0、pnpm 11.17.0、just 1.58.0，以及能运行 Linux 容器的 Docker / Compose。版本记录在 <code>rust-toolchain.toml</code>、<code>.node-version</code>、<code>package.json</code> 和 <code>.tool-versions</code>。</p><p>先取得本页对应的源码版本，在仓库根目录运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p><code>just dev</code> 启动 Docker 中的 PostgreSQL，显式运行迁移，再启动宿主机 API 与 Web。Web 支持 HMR；修改 Rust 源码会重新启动 API。没有 <code>.env</code> 时使用 <code>.env.example</code> 中的本地开发设置，需要调整时先复制为 <code>.env</code>。</p><p>打开 <a href="http://127.0.0.1:5173/" target="_blank" rel="noreferrer">http://127.0.0.1:5173/</a>。正常情况下会看到“服务已就绪”“PostgreSQL 已连接”和迁移版本 <code>1</code>。</p><p>API 默认监听 <code>127.0.0.1:3000</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/live</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/ready</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/api/v1/system/status</span></span></code></pre></div><p>每个响应都有 <code>x-request-id</code>。状态请求实际读取 PostgreSQL 的迁移记录，不是写死的前端展示数据。</p><h2 id="观察一个失败场景" tabindex="-1">观察一个失败场景 <a class="header-anchor" href="#观察一个失败场景" aria-label="Permalink to &quot;观察一个失败场景&quot;">​</a></h2><p>保持 <code>just dev</code> 运行，在另一个终端暂时停止开发数据库：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db-down</span></span></code></pre></div><p>再次点击页面的“重新检查”。页面显示失败提示和请求编号；<code>/health/ready</code> 返回 <code>503</code>，<code>/health/live</code> 仍返回 <code>200</code>。</p><p>恢复数据库后重新检查即可：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wait</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span></span></code></pre></div><p><code>Ctrl+C</code> 停止开发 API/Web，数据库与数据卷保留。<code>just db-down</code> 只停止数据库，不删除数据。</p><h2 id="文档与下一步" tabindex="-1">文档与下一步 <a class="header-anchor" href="#文档与下一步" aria-label="Permalink to &quot;文档与下一步&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span></code></pre></div><p>本地文档入口为 <a href="http://127.0.0.1:5174/axum-saas-template/" target="_blank" rel="noreferrer">http://127.0.0.1:5174/axum-saas-template/</a>。在线站点和本地站点使用同一组 Markdown 源文件。</p><p>复制模板后，按<a href="./getting-started/publish-docs">发布教程站点</a>启用自己的 GitHub Pages；后续合并到 <code>main</code> 时由 CI 检查并发布。</p><p>继续阅读<a href="./tutorials/first-request">第一条全栈请求</a>、<a href="./testing/feedback-loop">测试反馈循环</a>以及 <a href="./architecture/boundaries">Core/示例边界</a>。完整后续范围记录在<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/8e165cfcd7b4c566d51cff8c35b0a35e16f9ad8c/docs/saas-template-architecture-spec.md" target="_blank" rel="noreferrer">架构规范</a>。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>数据库能连接但 ready 仍失败</strong>：运行 <code>just migrate</code>；API 进程本身不自动迁移。</li><li><strong>端口已占用</strong>：修改 <code>.env</code> 中的 <code>APP_BIND</code> / <code>VITE_API_PROXY</code>；更改数据库端口时同时调整 <code>POSTGRES_PORT</code> 与 <code>DATABASE_URL</code>，然后重启开发入口。</li><li><strong>Rust 配置报错</strong>：检查<a href="./reference/config">生成的配置参考</a>。错误不会打印数据库凭据。</li><li><strong>浏览器请求失败</strong>：用 request_id 对照 API 的 JSON 日志；页面通过 Vite 同源代理访问 API，数据库 URL 不进入浏览器。</li></ul><hr><p>源码版本：<code>8e165cfcd7b4</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/8e165cfcd7b4c566d51cff8c35b0a35e16f9ad8c/docs/getting-started/quickstart.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,27)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
